pub(super) fn mux_row(
    em: &mut Em,
    lanes: &[Operand],
    base: usize,
    rows: usize,
    width: usize,
    index: Operand,
) -> (Operand, Vec<Operand>) {
    let mut out = vec![Em::imm(0); width];
    let mut hit_any = Em::imm(0);
    for r in 0..rows {
        let hit = em.teq(Em::imm(r as u128), index.clone());
