/// Infallible 17-lane control encoder.
pub fn encode_control(control: &ControlC) -> [u128; CONTROL_LANES] {
    use ControlC as K;
    let mut o = [0u128; CONTROL_LANES];
    match *control {
        K::Eval { expr } => o[1] = u(expr),
        K::Return { value } => {
            o[0] = 1;
            put_ref(&mut o, 1, value);
        }
        K::ScheduleNext { frame, next, env } => {
            o[0] = 2;
            o[1..1 + FRAME_LANES].copy_from_slice(&encode_frame(&frame));
            o[14] = u(next);
            put_env(&mut o, 15, env);
        env: rd(s, l[at + 2])?,
        value_slots: rd(s, l[at + 3])?,
    })
}
fn put_outcome(out: &mut [u128], at: usize, outcome: OutcomeC) {
    match outcome {
        OutcomeC::Running => {}
        OutcomeC::Halted { value } => {
            out[at] = 1;
            put_ref(out, at + 1, value);
        }
        OutcomeC::Rejected { code } => {
            out[at] = 2;
            out[at + 1] = u128::from(code);
        }
        OutcomeC::Exhausted { reason } => {
            out[at] = 3;
            out[at + 1] = exhaust_tag(reason);
        }
        OutcomeC::Waiting { site } => {
            out[at] = 4;
            out[at + 1] = u128::from(site);
        }
    }
